entries[1291682] = { ["name"] = "Odious Alloy", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nLuminant Flux (4), Umbral Tin Ore (6), Refulgent Copper Ingot (3)\nOptional Reagents:" }
entries[1291683] = { ["name"] = "Hunter's Ritual Stone", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nLuminant Flux (4), Neutralized Venom Clot (2), Cursebound Globe (2), Umbral Tin Ore (6), Refulgent Copper Ingot (3)\nOptional Reagents:\nVendor:\nConstruct V'anore\nZone:\nSilvermoon City\nCost:\n150\n500\n\nHunter's Ritual Stone\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Your damaging spells and abilities have a chance to grant 101 of a random secondary stat for 15 sec.\n\nWhile on a Prey Hunt this effect is increased by 50%. This bonus is only available outdoors while hunting prey.\nUsable with: Midnight Blacksmithing Weapons\n\"Crafted by players with the Blacksmithing skill. Can be bought and sold on the Auction House.\"" }
entries[1291687] = { ["name"] = "Coiled Snake-Eye", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (10), Neutralized Venom Clot (3), Evercore (5)\nOptional Reagents:\nDrop:\nWorld Creatures\n\nCoiled Snake-Eye\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property:\nYour damaging spells and abilties have a chance to grant 67 of a random secondary stat for 15 sec.\n\nIf this effect was triggered by a Critical Strike, it grants your highest secondary stat instead.\nUsable with: Midnight Engineering Guns\n\"Can be bought and sold on the Auction House.\"" }
