entries[1291690] = { ["name"] = "Polished Ammolite", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nNeutralized Venom Clot (6), Cursebound Globe (4), Sin'dorei Lens (2), Glimmering Gemdust (2)\nOptional Reagents:\nDrop:\nWorld Creatures\n\nPolished Ammolite\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Critical strikes bestow a stacking blessing that grants more Critical Strike. At maximum stacks, critical strikes cause a burst of damage.\nUsable with: Midnight recipes for most unembellished accessories.\n\"Can be bought and sold on the Auction House.\"" }
entries[1291691] = { ["name"] = "Adorned Fang", ["text"] = "2 sec cast\nReagents:\nNeutralized Venom Clot (6), Carving Canine , Peerless Plumage , Cursebound Globe (8), Void-Tempered Hide , Dusk-Shrouded Stone (2)\nOptional Reagents:\nDrop:\nThe Twin Fangs\nZone:\nThe Venomous Abyss\n\nAdorned Fang\n71\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Your spells and abilities have a chance to increase your Haste, with the chance increasing when a target is at lower health.\nUsable with: Midnight recipes for most unembellished equipment.\n\"Can be bought and sold on the Auction House.\"" }
entries[1291693] = { ["name"] = "Rally of the Coil", ["text"] = "3 sec cast\nOri'kassi bolsters nearby allies, increasing their damage done by 30% for 10 sec." }
entries[1291694] = { ["name"] = "Enchant Weapon - Rite of the Hash'ey", ["text"] = "2 sec cast 2\nTools: Runed Enchanting Rod\nReagents:\nCursebound Globe (5), Petrified Root (4), Flawless Amani Lapis , Eversinging Dust (20), Radiant Shard (10), Dawn Crystal (2)\nOptional Reagents:\nPermanently enchants a weapon with Rite of the Hash'ey, causing your spells and abilities to grant you Hash'ey's Might, granting you 80 of a random secondary stat for 15 sec and favors your highest secondary stat when you're above 80% health. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\nVendor:\nJan'sari the Watchful\nZone:\nThe Coiled Isle\nCost:\n150\n\nEnchant Weapon - Rite of the Hash'ey\n\nUse: Permanently enchants a weapon with Rite of the Hash'ey, causing your spells and abilities to grant you Hash'ey's Might, granting you 120 of a random secondary stat for 15 sec and favors your highest secondary stat when you're above 80% health. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\n70" }
